INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Energy Star nur für Computer relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Geräte"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt Energy Star?', 3, '[{"text": "Energieeffizienz fördern", "correct": true, "because": "Stromverbrauch senken"}, {"text": "Leistung steigern", "correct": false, "because": "Nicht primär"}, {"text": "Netzwerk verbessern", "correct": false, "because": "Kein Netzwerkfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte können Energy Star zertifiziert sein?', 5, '[{"text": "Computer", "correct": true, "because": "PCs und Laptops"}, {"text": "Drucker", "correct": true, "because": "Bürogeräte"}, {"text": "Papierdokumente", "correct": false, "because": "Keine Geräte"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Energy Star reduziert Energieverbrauch. b) Es gilt nur in Europa.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "International"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Energy Star?', 4, '[{"text": "Energieverbrauch", "correct": false, "because": "Kernkriterium"}, {"text": "Zertifizierungsstandards", "correct": false, "because": "Voraussetzung"}, {"text": "Gehäusefarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Energy Star von der EU entwickelt wurde?', 2, '[{"text": "Nein", "correct": true, "because": "EPA in den USA"}, {"text": "Ja", "correct": false, "because": "Nicht EU-Ursprung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Organisation steht hinter Energy Star?', 3, '[{"text": "EPA", "correct": true, "because": "Environmental Protection Agency"}, {"text": "ISO", "correct": false, "because": "Andere Standards"}, {"text": "DIN", "correct": false, "because": "Deutsche Norm"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Energy Star?', 5, '[{"text": "Kosteneinsparung", "correct": true, "because": "Weniger Strom"}, {"text": "Umweltschutz", "correct": true, "because": "CO₂-Reduktion"}, {"text": "Höhere Geschwindigkeit", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Energy Star zertifiziert energieeffiziente Geräte. b) Es ist nur für neue Geräte. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch ältere Geräte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Energy Star-Zertifizierung?', 4, '[{"text": "Energieeffizienztests", "correct": false, "because": "Pflicht"}, {"text": "Standards erfüllen", "correct": false, "because": "Voraussetzung"}, {"text": "Papierdokumente", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Energy Star ein Gesetz?', 2, '[{"text": "Nein", "correct": true, "because": "Freiwilliges Programm"}, {"text": "Ja", "correct": false, "because": "Kein Zwang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte profitieren von Energy Star?', 4, '[{"text": "Server", "correct": true, "because": "Hoher Energieverbrauch"}, {"text": "Monitore", "correct": true, "because": "Energieeffizienz"}, {"text": "Papierdrucker", "correct": false, "because": "Nicht spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Energy Star nur für Bürogeräte gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Haushaltsgeräte"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Energy Star?', 3, '[{"text": "Energieeinsparung", "correct": true, "because": "Hauptfokus"}, {"text": "Optisches Design", "correct": false, "because": "Irrelevant"}, {"text": "Maximale Leistung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Energy Star senkt Betriebskosten. b) Es ist ein EU-Gesetz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kein Gesetz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien gelten für Energy Star?', 5, '[{"text": "Energieverbrauch im Standby", "correct": true, "because": "Effizienz messen"}, {"text": "Betriebsleistung", "correct": true, "because": "Verbrauch prüfen"}, {"text": "Gewicht", "correct": false, "because": "Kein Kriterium"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Energy Star unwichtig?', 3, '[{"text": "Stromverbrauch", "correct": false, "because": "Kernkriterium"}, {"text": "Zertifizierungsprozess", "correct": false, "because": "Voraussetzung"}, {"text": "Verpackungsdesign", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss jedes Gerät Energy Star zertifiziert sein?', 3, '[{"text": "Nein", "correct": true, "because": "Freiwillig"}, {"text": "Ja", "correct": false, "because": "Kein Zwang"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Energy Star auch in Europa gilt?', 2, '[{"text": "Ja", "correct": true, "because": "International anerkannt"}, {"text": "Nein", "correct": false, "because": "Auch EU-Partner"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für Energy Star zentral?', 4, '[{"text": "Energieeffizienz", "correct": true, "because": "Kernprinzip"}, {"text": "Maximale Leistung", "correct": false, "because": "Nicht primär"}, {"text": "Papierdokumentation", "correct": false, "because": "Irrelevant"}]');
